param([string]$OutputPath)
$ErrorActionPreference='Stop'
$projectDir=Split-Path -Parent $PSScriptRoot
if(-not(Get-Command ConvertFrom-Markdown -ErrorAction SilentlyContinue)){throw 'Regenerating HTML requires PowerShell 7. Reading the prebuilt HTML needs only a browser.'}
if(-not $OutputPath){$OutputPath=Join-Path $projectDir 'START_HERE.html'}
$body=(ConvertFrom-Markdown -LiteralPath (Join-Path $projectDir 'START_HERE.md')).Html
$css=@'
:root{font-family:system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;color:#263d34;background:#f3f6f2;line-height:1.8}body{margin:0}main{max-width:1060px;margin:32px auto;background:white;border:1px solid #dee8dc;border-radius:20px;padding:42px 52px}.brand{color:#176743;font-size:13px;letter-spacing:2px;border-bottom:1px solid #e2e9df;padding-bottom:20px}h1{font-size:30px;line-height:1.45;margin:24px 0;color:#174e37}h2{font-size:24px;margin-top:42px;border-top:1px solid #e0e8de;padding-top:24px;color:#176743}h3{font-size:18px;margin-top:28px}p,li{font-size:15px}a{color:#176743;text-underline-offset:3px}strong{color:#174e37}pre{background:#f1f5ef;border:1px solid #e0e8db;border-radius:10px;padding:18px;font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}code{font-family:Consolas,"Microsoft YaHei",monospace}p code,li code,td code{background:#f0f4ed;padding:2px 5px;border-radius:4px;font-size:13px}table{border-collapse:collapse;width:100%;font-size:13px;margin:22px 0;line-height:1.7}th,td{border:1px solid #dce5d8;padding:12px 14px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#edf4e9;color:#24563b}tbody tr:nth-child(even){background:#fafcf8}blockquote{border-left:4px solid #538b63;margin:22px 0;padding:8px 20px;background:#f0f6eb}.footer{color:#71816f;font-size:12px;margin-top:38px;padding-top:18px;border-top:1px solid #e0e8dc}@media(max-width:800px){main{margin:0;border-radius:0;padding:24px 18px}h1{font-size:25px}table{font-size:12px}td,th{padding:7px}}@media print{@page{size:A4;margin:15mm}body{background:white}main{margin:0;padding:0;border:0;max-width:none}h1{font-size:24px}h2{font-size:19px;break-after:avoid}h3{break-after:avoid}p,li{font-size:10.5pt}table{font-size:9pt}th,td{padding:6px 8px}thead{display:table-header-group}tr,pre{break-inside:avoid}a{color:#254a36;text-decoration:none}pre{font-size:9pt}.brand{font-size:10pt}}
'@
$html='<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>青境｜新设备安装与操作指南</title><style>'+$css+'</style></head><body><main><div class="brand">青境 QINGJING · TRANSFER GUIDE · 2026.10.20</div>'+$body+'<div class="footer">离线阅读文档。完整源码和成品见同批交付包；业务恢复前先确认目标库。可使用浏览器“打印 → 保存为PDF”。</div></main></body></html>'
[IO.File]::WriteAllText($OutputPath,$html,(New-Object Text.UTF8Encoding($false)))
Write-Host ('Guide generated: '+$OutputPath)
